def _decode(x, coef):
    from scipy.optimize import least_squares
    (offset, gain) = (coef[:4], coef[4:8])
    (coupling, interaction, cubic) = coef[8:]
    i = np.arange(4)
    j = (i + 1) % 4

    def residual(z, row):
        nxt = z[j]
        return offset + gain * z + coupling * nxt + interaction * z * nxt + cubic * z ** 3 - row

    def jacobian(z, row):
        g = np.diag(gain + interaction * z[j] + 3 * cubic * z * z)
        g[i, j] = coupling + interaction * z
        return g
    z = []
    for row in x:
        result = least_squares(residual, (row - offset) / gain, jac=jacobian, args=(row,), gtol=1e-12, max_nfev=80)
        if np.linalg.norm(result.fun, np.inf) > 1e-08:
            other = least_squares(residual, np.zeros(4), jac=jacobian, args=(row,), gtol=1e-12, max_nfev=100)
            if np.linalg.norm(other.fun) < np.linalg.norm(result.fun):
                result = other
        z.append(result.x)
    return np.asarray(z).reshape(-1, 4)

def _operator(panel):
    from scipy.optimize import least_squares
    (u, v) = [np.asarray(panel[k], dtype=float) for k in ('u', 'v')]

    def residual(p):
        a = _affine(_warp(u, p))
        return (a @ _fit(a, v) - v).ravel()
    scale = np.max(np.abs(u))
    p = least_squares(residual, [0.25 * scale, 1.5], bounds=([0.0, 0.5], [0.8 * scale, 3.5]), ftol=1e-11, xtol=1e-11, gtol=1e-11).x
    return (p, _fit(_affine(_warp(u, p)), v))

def _features(z, w):
    from itertools import combinations_with_replacement
    base = np.column_stack((_affine(w), z * np.roll(w, 1, axis=1)))
    quad = np.column_stack([w[:, i] * w[:, j] for (i, j) in combinations_with_replacement(range(4), 2)])
    return (base, quad)

def _scalar(z, w, nt, y):
    from scipy.optimize import minimize_scalar
    (base, quad) = _features(z, w)
    d = z[:, 3]

    def fit(q, predict=False):
        den = 1 + q * d * d
        design = np.c_[base[:, :5] / den[:, None], base[:, 5:], quad, d, d / den]
        train = design[:nt]
        coef = _fit(train, y)
        return design[nt:] @ coef if predict else np.sum((train @ coef - y) ** 2)
    q = minimize_scalar(fit, bounds=(0.025, 0.8), method='bounded').x
    return fit(q, True)
